174	// 下载失败、领取前版本不兼容都按现有方式结束，不产生回滚。
175	func TestDownloadFailureAndIncompatibleNoRollback(t *testing.T) {
176		// 下载失败。
177		s := setupUpgrade(t, "d1")
178		spec := rbSpec()
179		createCampaign(t, s, spec)
180		bringOnline(t, s, "d1")
181		dl, _ := s.Claim(spec.ID, "d1", upBase.Add(2*time.Minute))
182		if err := s.SubmitResult(OperationResult{
183			CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
184			At: upBase.Add(3 * time.Minute), Success: false, Reason: "dl down",
185		}); err != nil {
186			t.Fatal(err)
187		}
188		v, _ := s.GetCampaign(spec.ID)
189		d := findDevice(v, "d1")
190		if d.Status != DeviceFailed || d.Phase != StageDownload || d.RollbackResult {
191			t.Fatalf("download failure ends without rollback: %+v", d)
192		}
193		if !v.Ended {
194			t.Fatal("campaign ends on download failure")
195		}
196	
197		// 领取前不兼容：普通上报把版本改成不兼容版本，领取即失败，无回滚。
198		s2, dir2 := setupUpgradeDir(t, "x1")
199		spec2 := rbSpec()
200		spec2.ID = "cmp-2"
201		spec2.Devices = []string{"x1"}
202		createCampaign(t, s2, spec2)
203		bringOnline(t, s2, "x1")
204		if err := s2.Report("x1", 2, upBase.Add(time.Minute), "v9", json.RawMessage(`{}`)); err != nil {
205			t.Fatal(err)
206		}
207		if _, err := s2.Claim(spec2.ID, "x1", upBase.Add(2*time.Minute)); !errors.Is(err, ErrIncompatibleVersion) {
208			t.Fatalf("incompatible claim: %v", err)
209		}
210		v2, _ := s2.GetCampaign(spec2.ID)
211		x := findDevice(v2, "x1")
212		if x.Status != DeviceFailed || x.Phase != StageDownload ||
213			x.RollbackResult || x.RollbackTarget != "" {
214			t.Fatalf("incompatible before claim must not rollback: %+v", x)
215		}
216		// 该边界状态（已领取下载但未锁定目标）必须能正常持久化重开。
217		if err := s2.Close(); err != nil {
218			t.Fatal(err)
219		}
220		s3, err := Open(dir2)
221		if err != nil {
222			t.Fatalf("reopen incompatible-claim store: %v", err)
223		}
224		defer s3.Close()
225		v3, _ := s3.GetCampaign(spec2.ID)
226		if x3 := findDevice(v3, "x1"); x3.Status != DeviceFailed || x3.RollbackTarget != "" {
227			t.Fatalf("state after reopen: %+v", x3)
228		}
229	}
