231	// 回滚首次领取要求在线且位于窗口 [start,end)；离线保留待办；
232	// 待办查询显示回滚目标与未领取；已领取操作再次查询（含窗口外）返回同一标识。
233	func TestRollbackClaimWindowOnlineAndStableID(t *testing.T) {
234		s := setupUpgrade(t, "d1")
235		spec := rbSpec()
236		spec.WindowEnd = upBase.Add(30 * time.Minute) // 窗口 12:00–12:30
237		createCampaign(t, s, spec)
238		bringOnline(t, s, "d1")
239		inID, _ := awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
240	
241		// 离线且位于窗口内：保留待办。
242		if err := s.SetOffline("d1"); err != nil {
243			t.Fatal(err)
244		}
245		if op, err := s.Claim(spec.ID, "d1", upBase.Add(10*time.Minute)); err != nil || op != nil {
246			t.Fatalf("offline rollback waits: %v %+v", err, op)
247		}
248		w, _ := s.GetDeviceWork("d1")
249		if w.Pending == nil || w.Pending.Kind != StageRollback || w.PendingClaimed {
250			t.Fatalf("pending rollback unclaimed: %+v", w)
251		}
252		if w.Pending.TargetVersion != "v1" {
253			t.Fatalf("work shows rollback target: %+v", w.Pending)
254		}
255		// 上线（普通上报不改变回滚待办）。
256		if err := s.Report("d1", 2, upBase.Add(11*time.Minute), "v1", json.RawMessage(`{}`)); err != nil {
257			t.Fatal(err)
258		}
259	
260		// 仍在窗口内：可领取。
261		rb, err := s.Claim(spec.ID, "d1", upBase.Add(12*time.Minute))
262		if err != nil || rb == nil {
263			t.Fatalf("claim rollback in window: %v %+v", err, rb)
264		}
265		if rb.Kind != StageRollback || rb.TargetVersion != "v1" ||
266			rb.ID != encodeOperationIDV2(0, spec.ID, "d1", StageRollback) {
267			t.Fatalf("rollback op: %+v", rb)
268		}
269		if rb.ID == inID || rb.ID == encodeOperationIDV2(0, spec.ID, "d1", StageDownload) {
270			t.Fatalf("rollback id must differ from download/install: %s", rb.ID)
271		}
272		// 正在回滚的设备同样不能参加其他活动。
273		other := spec
274		other.ID = "cmp-other"
275		other.CreatedAt = upBase.Add(time.Minute)
276		if err := s.CreateCampaign(other); !errors.Is(err, ErrDeviceBusy) {
277			t.Fatalf("rolling-back device busy: %v", err)
278		}
279		// 窗口外再次查询：返回同一已领取标识与锁定目标。
280		again, err := s.Claim(spec.ID, "d1", upBase.Add(45*time.Minute))
281		if err != nil || again == nil || again.ID != rb.ID || again.TargetVersion != "v1" {
282			t.Fatalf("claimed rollback returns same id: %v %+v", err, again)
283		}
284	}
