286	// 设备在线但窗口外时，回滚首次领取保留待办（未领取、带目标版本）。
287	func TestRollbackClaimWaitsOutsideWindow(t *testing.T) {
288		s := setupUpgrade(t, "d1")
289		spec := rbSpec()
290		spec.WindowEnd = upBase.Add(30 * time.Minute)
291		createCampaign(t, s, spec)
292		bringOnline(t, s, "d1")
293		awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
294	
295		// 窗口结束之后、截止之前：在线也暂不派发回滚。
296		if op, err := s.Claim(spec.ID, "d1", upBase.Add(45*time.Minute)); err != nil || op != nil {
297			t.Fatalf("rollback waits outside window: %v %+v", err, op)
298		}
299		if d := findDevice(mustGetCampaign(s, spec.ID), "d1"); d.Status != DeviceAwaitingRollback {
300			t.Fatalf("still awaiting: %+v", d)
301		}
302		w, _ := s.GetDeviceWork("d1")
303		if w.Pending == nil || w.Pending.Kind != StageRollback || w.PendingClaimed ||
304			w.Pending.TargetVersion != "v1" {
305			t.Fatalf("unclaimed rollback todo outside window: %+v", w)
306		}
307	}
