398	// 回滚失败必须给出原因；设备以回滚失败结束且影子不变。
399	func TestRollbackFailureRequiresReasonAndKeepsShadow(t *testing.T) {
400		s := setupUpgrade(t, "d1")
401		spec := rbSpec()
402		createCampaign(t, s, spec)
403		bringOnline(t, s, "d1")
404		_, failAt := awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
405		rb, _ := s.Claim(spec.ID, "d1", upBase.Add(8*time.Minute))
406	
407		if err := s.SubmitResult(OperationResult{
408			CampaignID: spec.ID, DeviceID: "d1", OperationID: rb.ID,
409			At: upBase.Add(9 * time.Minute), Success: false,
410		}); !errors.Is(err, ErrInvalidReason) {
411			t.Fatalf("rollback failure needs reason: %v", err)
412		}
413		rbFailAt := upBase.Add(10 * time.Minute)
414		if err := s.SubmitResult(OperationResult{
415			CampaignID: spec.ID, DeviceID: "d1", OperationID: rb.ID,
416			At: rbFailAt, Success: false, Reason: "rb boom",
417		}); err != nil {
418			t.Fatalf("rollback failure: %v", err)
419		}
420		v, _ := s.Get("d1")
421		if v.Version != "v1" || v.LastSeq != 1 {
422			t.Fatalf("shadow must not change on rollback failure: %+v", v)
423		}
424		cv, _ := s.GetCampaign(spec.ID)
425		d := findDevice(cv, "d1")
426		if d.Status != DeviceRollbackFailed || d.Phase != StageRollback ||
427			d.RollbackReason != "rb boom" || !d.RollbackAt.Equal(rbFailAt) {
428			t.Fatalf("rollback failure record: %+v", d)
429		}
430		// 安装失败与回滚结果的原因/时间可分别查看。
431		if d.InstallFailReason != "install broken" || !d.InstallFailAt.Equal(failAt) {
432			t.Fatalf("install failure kept separately: %+v", d)
433		}
434		if !d.RollbackResult || d.RollbackSuccess {
435			t.Fatalf("rollback result flags: %+v", d)
436		}
437		if !cv.Ended || cv.Status != CampaignFailed {
438			t.Fatalf("campaign: %+v", cv)
439		}
440	}
