472		// 领取回滚并提交失败。
473		rb, _ := s.Claim(spec.ID, "d1", upBase.Add(8*time.Minute))
474		if err := s.SubmitResult(OperationResult{
475			CampaignID: spec.ID, DeviceID: "d1", OperationID: rb.ID,
476			At: upBase.Add(9 * time.Minute), Success: false, Reason: "rb boom",
477		}); err != nil {
