1107	// GetCampaign 查询活动：创建者、目标版本、每批设备状态、
1108	// 失败或超时原因及结果历史。返回数据为独立副本。
1109	func (s *Store) GetCampaign(campaignID string) (CampaignView, error) {
1110		s.mu.Lock()
1111		defer s.mu.Unlock()
1112		if err := s.checkOpen(); err != nil {
1113			return CampaignView{}, err
1114		}
1115		c, err := s.lookupCampaign(campaignID)
1116		if err != nil {
1117			return CampaignView{}, err
1118		}
1119		v := CampaignView{
1120			ID:                c.ID,
1121			Operator:          c.Operator,
1122			TargetVersion:     c.Target,
1123			CreatedAt:         c.CreatedAt,
1124			BatchSize:         c.BatchSize,
1125			WindowStart:       c.WindowStart,
1126			WindowEnd:         c.WindowEnd,
1127			Deadline:          c.Deadline,
1128			RollbackOnFailure: c.RollbackOnFailure,
1129			Status:            c.Status,
1130			Ended:             c.Ended,
1131			EndedAt:           c.EndedAt,
1132			Results:           make([]ResultRecord, len(c.Results)),
1133		}
1134		copy(v.Results, c.Results)
1135		for _, cd := range c.Devices {
1136			dv := DeviceStatusView{
1137				DeviceID:       cd.DeviceID,
1138				Batch:          cd.Batch,
1139				Status:         cd.Status,
1140				Phase:          cd.Phase,
1141				Reason:         cd.Reason,
1142				At:             cd.At,
1143				DownloadID:     cd.Download.ID,
1144				InstallID:      cd.Install.ID,
1145				RollbackID:     cd.Rollback.ID,
1146				RollbackTarget: cd.RollbackTarget,
1147			}
1148			// 安装失败原因与时间独立保留，进入回滚后也不被回滚结果覆盖。
1149			if cd.Install.HasResult && !cd.Install.Success {
1150				dv.InstallFailReason = cd.Install.Reason
1151				dv.InstallFailAt = cd.Install.At
1152			}
1153			// 回滚结果的原因与时间单独呈现。
1154			if cd.Rollback.HasResult {
1155				dv.RollbackResult = true
1156				dv.RollbackSuccess = cd.Rollback.Success
1157				dv.RollbackReason = cd.Rollback.Reason
1158				dv.RollbackAt = cd.Rollback.At
1159			}
1160			v.Devices = append(v.Devices, dv)
1161			for len(v.Batches) <= cd.Batch {
1162				v.Batches = append(v.Batches, BatchView{Index: len(v.Batches)})
1163			}
1164			v.Batches[cd.Batch].Devices = append(v.Batches[cd.Batch].Devices, dv)
1165		}
1166		return v, nil
1167	}
