		if !errors.Is(err, ErrIncompatibleVersion) {
			t.Fatalf("claim must fail incompatible: %v", err)
		}
		d := findDevice(mustGetCampaign(s, spec.ID), "d1")
		if d.Status != DeviceFailed || d.Phase != StageDownload || d.RollbackTarget != "" {
