		}
		// 下载已领取、目标已锁定为 v1；此后普通上报只改影子，不改锁定目标。
		if err := s.Report("d1", 2, upBase.Add(30*time.Second), "v9", json.RawMessage(`{}`)); err != nil {
			t.Fatalf("report: %v", err)
		}
