354			t.Fatalf("since should restart: %+v", diffs)
355		}
356		// 离线和重复上报不刷新差异时间
357		if err := s.SetOffline("dev-1"); err != nil {
358			t.Fatal(err)
359		}
360		if err := s.Report("dev-1", 1, t3, "1.0", json.RawMessage(`{"a":2}`)); err != nil {
